function readRooms(){try{return JSON.parse(localStorage.getItem(ROOM_KEY)||'[]').filter(r=>Date.now()-r.updated<120000&&r.players<8)}catch{return[]}}
function writeRooms(rooms){try{localStorage.setItem(ROOM_KEY,JSON.stringify(rooms))}catch{}renderRoomList()}
function createRoom(){const code=('NS'+Math.random().toString(36).slice(2,7)).toUpperCase();hostId=id;$('#roomInput').value=code;const rooms=readRooms();rooms.push({code,host:($('#nameInput').value||'PLAYER').toUpperCase(),hostId,players:0,created:Date.now(),updated:Date.now()});writeRooms(rooms);enterLobby()}
function joinByCode(){const code=$('#roomInput').value.trim().toUpperCase();if(!code){$('#roomInput').focus();return}const room=readRooms().find(r=>r.code===code);hostId=room?.hostId||'';$('#roomInput').value=code;enterLobby()}
function quickStart(){const rooms=readRooms().sort((a,b)=>b.players-a.players||a.created-b.created);if(rooms.length){hostId=rooms[0].hostId||'';$('#roomInput').value=rooms[0].code;enterLobby()}else createRoom()}
