function heartbeatRoom(){if(!roomRegistered)return;const rooms=readRooms(),found=rooms.find(r=>r.code===currentRoom);if(found){found.updated=Date.now();found.players=Math.max(found.players,lobbyPlayers.size||1);writeRooms(rooms)}}
function leaveRegistry(){if(!roomRegistered)return;const rooms=readRooms(),found=rooms.find(r=>r.code===currentRoom);if(found){found.players=Math.max(0,found.players-1);found.updated=Date.now()}roomRegistered=false;writeRooms(rooms.filter(r=>r.players>0))}
function renderRoomList(){const list=$('#roomList');if(!list)return;const rooms=readRooms();list.innerHTML='';if(!rooms.length){list.innerHTML='<div class="no-rooms">NO ACTIVE ROOMS - CREATE THE FIRST ONE</div>';return}for(const room of rooms){const row=document.createElement('div');row.className='room-item';row.innerHTML=`<div><b>${room.code}</b><small>HOST: ${room.host}</small></div><div class="population">${room.players} / 8</div><button>JOIN</button>`;row.querySelector('button').onclick=()=>{$('#roomInput').value=room.code;joinByCode()};list.appendChild(row)}}
