function selectLobbyMap(name,broadcast){if(!MAPS[name]||(broadcast&&!lobbyHost()))return;currentMap=name;$('#mapSelect').value=name;$('#waitingMapName').textContent=MAPS[name].name;$('#waitingMapDesc').textContent=MAPS[name].desc;renderMapPreview(name);if(broadcast)send('mapselect',{map:name})}
function renderMapPreview(name,target='#mapPreviewCanvas'){const canvas=$(target);if(!canvas)return;const c=canvas.getContext('2d'),data=MAPS[name].data,palette=MAPS[name].wall,mw=data[0].length,mh=data.length,s=Math.min(canvas.width/mw,canvas.height/mh),ox=(canvas.width-mw*s)/2,oy=(canvas.height-mh*s)/2;c.clearRect(0,0,canvas.width,canvas.height);c.fillStyle='#080d10';c.fillRect(0,0,canvas.width,canvas.height);c.fillStyle='rgba(255,56,93,.24)';c.fillRect(ox,oy,mw*s,s*6);c.fillStyle='rgba(40,231,255,.24)';c.fillRect(ox,oy+(mh-6)*s,mw*s,s*6);for(let y=0;y<mh;y++)for(let x=0;x<mw;x++)if(data[y][x]==='1'){const k=(x+y)%2?.82:1;c.fillStyle=`rgb(${palette.map(v=>Math.round(v*k)).join(',')})`;c.fillRect(ox+x*s,oy+y*s,Math.max(.6,s+.1),Math.max(.6,s+.1))}c.strokeStyle='rgba(235,245,247,.45)';c.lineWidth=1;c.strokeRect(ox+.5,oy+.5,mw*s-1,mh*s-1);c.fillStyle='#ff385d';c.beginPath();c.arc(canvas.width/2,oy+s*7.5,3,0,7);c.fill();c.fillStyle='#28e7ff';c.beginPath();c.arc(canvas.width/2,oy+(mh-7.5)*s,3,0,7);c.fill()}
