function showLoading(){const info=MAPS[currentMap],roster=[...lobbyPlayers.values()];$('#loadingMapName').textContent=info.name;$('#loadingMapDesc').textContent=info.desc;$('#loadWeapon').textContent=WEAPONS[player.weapon].name;const allies=roster.filter(p=>p.team===player.team).map(p=>p.name+' / '+WEAPONS[p.weapon]?.name),enemies=roster.filter(p=>p.team!==player.team).map(p=>p.name+' / '+WEAPONS[p.weapon]?.name);if(solo&&currentMap==='training'){allies.push('LIVE FIRE DRILL');enemies.push('8 REACTIVE TARGETS')}else if(solo){allies.push('NOVA / K2','RAZE / M16');enemies.push('VEX / AK-47','GHOST / K2','BYTE / M16')}$('#loadAllies').innerHTML=(allies.length?allies:['AWAITING UNIT']).join('<br>');$('#loadEnemies').innerHTML=(enemies.length?enemies:['UNKNOWN CONTACT']).join('<br>');$('#loadingScreen').classList.remove('hidden');const bar=$('#loadProgress');bar.style.animation='none';void bar.offsetWidth;bar.style.animation='loadfill 3s linear forwards'}
