function makeTargets(){return [[9.5,13.5],[11.5,13.5],[9.5,8.5],[11.5,8.5],[9.5,4.2],[11.5,4.2],[3.5,8.5],[17.5,8.5]].map((p,i)=>({id:'target'+i,x:p[0],y:p[1],type:'target',r:.24,name:'TARGET '+(i+1),dead:false}))}
