function makeBot(i){const botTeam=i%2?'blue':'red',guns=['ak47','k2','m16','ak47','k2'];let p;if(botTeam==='red'){p=[player.x+(i===0?.15:-.35),player.y-(i===0?4:5.2)];if(wall(p[0],p[1])){const pts=teamSpawns('red');p=pts[i%pts.length]}}else{p=[player.x+(i===1?.55:-.55),player.y-1.7];if(wall(p[0],p[1])){const pts=teamSpawns('blue');p=pts[i%pts.length]}}return{id:'bot'+i,x:p[0],y:p[1],a:Math.atan2(player.y-p[1],player.x-p[0]),hp:100,weapon:guns[i],name:['VEX','NOVA','GHOST','RAZE','BYTE'][i],team:botTeam,bot:true,dead:false,cool:.8+i*.15,stuck:0,walk:i*.8,moving:true,muzzle:0}}
