function send(type,extra={}){if(channel)channel.postMessage({type,id,...player,...extra})}
function receive(d){if(d.id===id)return;if(d.type==='chat'){addChat(d.name,d.message);return}if(d.type==='pause'){applyPause(d.ownerId||d.id,d.ownerName||d.name);return}if(d.type==='resume'){if(matchPaused&&d.ownerId===pauseOwner)applyResume();return}if(d.type==='surrenderVote'){registerSurrenderVote(d.voterId||d.id,d.voterTeam||d.team);return}if(d.type==='lobbyjoin'||d.type==='ready'){lobbyPlayers.set(d.id,{id:d.id,name:d.name,team:d.team,weapon:d.weapon,ready:!!d.ready});updateLobby();if(d.type==='lobbyjoin'){send('ready',{ready:isReady});if(lobbyHost())send('mapselect',{map:currentMap})}return}if(d.type==='mapselect'){selectLobbyMap(d.map,false);return}if(d.type==='countdown'){showCountdown(d.value);return}if(d.type==='countdowncancel'){cancelCountdown(false);return}if(d.type==='matchstart'){cancelCountdown(false);start(false,d.map);return}if(d.type==='matchend'){finishMatch(d.winner,false);return}if(d.type==='score'){blue=d.blue;red=d.red;updateHUD();return}if(d.type==='leave'){others.delete(d.id);lobbyPlayers.delete(d.id);if(matchPaused&&pauseOwner===d.id)applyResume();updateLobby()}else if(d.type==='shot'&&d.target===id)damage(d.damage,d.name);else if(d.type==='death'){if(d.killer===player.name)player.kills++;if((d.assists||[]).includes(player.name))player.assists++;feed(d.killer,d.name);const old=others.get(d.id)||d;others.set(d.id,{...old,...d,dead:true,seen:Date.now()});send('state')}else{const old=others.get(d.id),moving=!!old&&Math.hypot(d.x-old.x,d.y-old.y)>.005,walk=(old?.walk||0)+(moving?.32:0);others.set(d.id,{...d,moving,walk,seen:Date.now()});if(d.type==='join')send('state')}}
function toggleReady(){isReady=!isReady;const me=lobbyPlayers.get(id);if(me)me.ready=isReady;$('#readyBtn').textContent=isReady?'NOT READY':'READY';$('#readyBtn').classList.toggle('active',isReady);send('ready',{ready:isReady});updateLobby()}
function updateLobby(){const list=$('#playerList');if(!list)return;list.innerHTML='';const roster=[...lobbyPlayers.values()];for(const p of roster){const row=document.createElement('div');row.className='player-row '+p.team;row.innerHTML=`<div class="avatar">${p.name.slice(0,2)}</div><div><b>${p.name}${p.id===id?' (YOU)':''}</b><small>${p.team.toUpperCase()} TEAM</small></div><div class="gun">${WEAPONS[p.weapon]?.name||'K2'}</div><div class="ready ${p.ready?'on':''}">${p.ready?'READY':'WAITING'}</div>`;list.appendChild(row)}for(let i=roster.length;i<4;i++){const e=document.createElement('div');e.className='empty-slot';e.textContent='OPEN OPERATOR SLOT';list.appendChild(e)}$('#playerCount').textContent=roster.length+' / 8';const allReady=roster.length>0&&roster.every(p=>p.ready),host=lobbyHost();$('#hostBadge').classList.toggle('hidden',!host);$('#mapSelect').disabled=!host;$('#lobbyStatus').textContent=allReady?'All operators ready. Auto deployment starting...':'Waiting for operators to ready up...';$('#startMatchBtn').disabled=!allReady||!host;if(allReady&&host&&!countdownTimer)beginCountdown();if(!allReady&&countdownTimer)cancelCountdown(true)}
function beginCountdown(){let value=5;showCountdown(value);send('countdown',{value});countdownTimer=setInterval(()=>{value--;if(value<=0){clearInterval(countdownTimer);countdownTimer=null;launchMatch()}else{showCountdown(value);send('countdown',{value})}},1000)}
function showCountdown(value){$('#countdownValue').textContent=value;$('#countdownPanel').classList.remove('hidden')}
function cancelCountdown(notify){if(countdownTimer){clearInterval(countdownTimer);countdownTimer=null}$('#countdownPanel').classList.add('hidden');if(notify)send('countdowncancel')}
addEventListener('keydown',e=>{if(e.code==='Enter'&&playing&&!solo&&!matchPaused&&!chatOpen&&!surrenderOpen){e.preventDefault();openChat();return}if(chatOpen||matchPaused)return;if(e.code==='Escape'&&solo&&currentMap==='training'){e.preventDefault();exitTraining();return}if(e.code==='Escape'&&playing&&!solo){e.preventDefault();if(!surrenderOpen)openSurrender();return}if(surrenderOpen)return;initAudio();keys[e.code]=1;if(e.code==='KeyR')reload();if(e.code==='Digit1')selectWeapon('k2');if(e.code==='Digit2')selectWeapon('ak47');if(e.code==='Digit3')selectWeapon('m16')});addEventListener('keyup',e=>keys[e.code]=0);$('#chatInput').addEventListener('keydown',e=>{e.stopPropagation();if(e.code==='Enter'){e.preventDefault();submitChat()}else if(e.code==='Escape'){e.preventDefault();closeChat()}});canvas.addEventListener('mousedown',e=>{initAudio();if(!playing||matchPaused||chatOpen||surrenderOpen)return;if(document.pointerLockElement!==canvas)canvas.requestPointerLock().catch(()=>{});if(e.button===0){firing=true;shoot()}if(e.button===2)toggleAim()});addEventListener('mouseup',e=>{if(e.button===0)firing=false});canvas.addEventListener('wheel',adjustZoom,{passive:false});canvas.addEventListener('contextmenu',e=>e.preventDefault());addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&!player.dead&&!matchPaused&&!chatOpen&&!surrenderOpen){const sensitivity=.0025*(aiming?Math.max(.28,FOV/(Math.PI/3)):.98);player.a+=e.movementX*sensitivity;player.pitch=Math.max(-1.05,Math.min(1.05,player.pitch+e.movementY*sensitivity))}});document.addEventListener('pointerlockchange',()=>{firing=false;if(!playing)return;if(solo&&currentMap==='training'&&document.pointerLockElement!==canvas){exitTraining();return}if(matchPaused){$('#pause').classList.remove('hidden');return}if(!solo&&!chatOpen&&!surrenderOpen&&document.pointerLockElement!==canvas){openSurrender();return}if(solo)$('#pause').classList.toggle('hidden',document.pointerLockElement===canvas);else $('#pause').classList.add('hidden')});addEventListener('beforeunload',()=>{send('leave');leaveRegistry()});addEventListener('storage',e=>{if(e.key===ROOM_KEY)renderRoomList()});setInterval(heartbeatRoom,30000);renderRoomList();renderMapPreview('sector9','#botMapPreviewCanvas');
function openChat(){if(!playing||solo||matchPaused)return;chatOpen=true;firing=false;keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=0;if(document.pointerLockElement)document.exitPointerLock();$('#chatPanel').classList.remove('hidden');$('#chatInput').value='';$('#chatInput').focus()}
function closeChat(){chatOpen=false;$('#chatPanel').classList.add('hidden');if(playing&&!matchPaused)canvas.requestPointerLock().catch(()=>{})}
function submitChat(){const message=$('#chatInput').value.trim();if(!message){closeChat();return}if(message.toLowerCase()==='/paused'){closeChat();if(!matchPaused&&!solo){send('pause',{ownerId:id,ownerName:player.name});applyPause(id,player.name)}return}addChat(player.name,message);send('chat',{message});closeChat()}
function addChat(name,message){const row=document.createElement('div'),who=document.createElement('b'),text=document.createElement('span');who.textContent=(name||'PLAYER')+':';text.textContent=message;row.append(who,text);$('#chatLog').appendChild(row);while($('#chatLog').children.length>8)$('#chatLog').firstChild.remove();setTimeout(()=>row.remove(),10000)}
function applyPause(owner,name){if(solo||!playing||matchPaused)return;matchPaused=true;pauseOwner=owner;pauseOwnerName=name||'PLAYER';pauseStarted=performance.now();firing=false;keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=0;chatOpen=false;$('#chatPanel').classList.add('hidden');if(document.pointerLockElement)document.exitPointerLock();$('#pauseMessage').textContent=pauseOwner===id?'You paused the match. Click RESUME to continue.':pauseOwnerName+' paused the match. Waiting for that player to resume.';$('#resumeBtn').disabled=pauseOwner!==id;$('#resumeBtn').textContent=pauseOwner===id?'RESUME':'WAITING';$('#pause').classList.remove('hidden');addChat('SYSTEM',pauseOwnerName+' paused the match.')}
function applyResume(){if(!matchPaused)return;const held=performance.now()-pauseStarted;endAt+=held;matchStartedAt+=held;if(reloading){reloadStart+=held;reloadEnd+=held}matchPaused=false;pauseOwner='';pauseOwnerName='';pauseStarted=0;$('#pause').classList.add('hidden');$('#resumeBtn').disabled=false;$('#resumeBtn').textContent='RESUME';addChat('SYSTEM','Match resumed.');last=performance.now();canvas.requestPointerLock().catch(()=>{})}
function openSurrender(){if(!playing||solo||matchPaused)return;surrenderOpen=true;firing=false;keys.KeyW=keys.KeyA=keys.KeyS=keys.KeyD=0;if(document.pointerLockElement)document.exitPointerLock();updateSurrenderPanel();$('#surrenderModal').classList.remove('hidden')}
function closeSurrender(){surrenderOpen=false;$('#surrenderModal').classList.add('hidden');if(playing&&!matchPaused)canvas.requestPointerLock().catch(()=>{})}
function teamVoteNeed(side){const members=[...lobbyPlayers.values()].filter(p=>p.team===side).length||1;return Math.floor(members/2)+1}
function formatLockTime(ms){const total=Math.ceil(ms/1000);return String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0')}
function updateSurrenderPanel(){if(!surrenderOpen)return;const elapsed=Date.now()-matchStartedAt,remaining=Math.max(0,300000-elapsed),votes=surrenderVotes[player.team].size,needed=teamVoteNeed(player.team),eligible=remaining<=0,already=surrenderVotes[player.team].has(id),lockTime=formatLockTime(remaining);$('#surrenderVotes').textContent=votes;$('#surrenderNeeded').textContent=needed;$('#surrenderMessage').textContent=eligible?'A majority vote will surrender the match for '+player.team.toUpperCase()+' TEAM.':'Surrender voting unlocks in '+lockTime+'.';$('#surrenderVoteBtn').disabled=!eligible||already;$('#surrenderVoteBtn').textContent=already?'VOTE SUBMITTED':eligible?'VOTE TO SURRENDER':'LOCKED '+lockTime}
function castSurrenderVote(){if(Date.now()-matchStartedAt<300000||surrenderVotes[player.team].has(id))return;registerSurrenderVote(id,player.team);send('surrenderVote',{voterId:id,voterTeam:player.team})}
function registerSurrenderVote(voter,side){if(!playing||solo||!surrenderVotes[side])return;surrenderVotes[side].add(voter);addChat('SYSTEM',side.toUpperCase()+' team surrender vote: '+surrenderVotes[side].size+'/'+teamVoteNeed(side));updateSurrenderPanel();if(surrenderVotes[side].size>=teamVoteNeed(side)){const winner=side==='blue'?'RED':'BLUE';finishMatch(winner,false)}}
function initAudio(){if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();noiseBuffer=audioCtx.createBuffer(1,audioCtx.sampleRate*.35,audioCtx.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1}if(audioCtx.state==='suspended')audioCtx.resume()}
function audioOutput(volume,pan){const gain=audioCtx.createGain();gain.gain.value=volume;let last=gain;if(audioCtx.createStereoPanner){const p=audioCtx.createStereoPanner();p.pan.value=Math.max(-1,Math.min(1,pan||0));gain.connect(p);last=p}last.connect(audioCtx.destination);return gain}
function playGunSound(weapon,volume=1,pan=0){if(!audioCtx)return;const now=audioCtx.currentTime,gun=weapon||'k2',out=audioOutput(volume,pan),noise=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter(),boom=audioCtx.createOscillator(),boomGain=audioCtx.createGain();noise.buffer=noiseBuffer;filter.type='bandpass';filter.frequency.value=gun==='ak47'?1250:gun==='m16'?1900:1550;filter.Q.value=.6;noise.connect(filter);filter.connect(out);out.gain.setValueAtTime(volume,now);out.gain.exponentialRampToValueAtTime(.001,now+(gun==='ak47'?.22:.14));boom.type='triangle';boom.frequency.setValueAtTime(gun==='ak47'?105:gun==='m16'?145:125,now);boom.frequency.exponentialRampToValueAtTime(48,now+.12);boomGain.gain.setValueAtTime(volume*.55,now);boomGain.gain.exponentialRampToValueAtTime(.001,now+.16);boom.connect(boomGain);boomGain.connect(audioCtx.destination);noise.start(now);noise.stop(now+.25);boom.start(now);boom.stop(now+.18)}
function playFootstep(volume=.22,pan=0){if(!audioCtx)return;const now=audioCtx.currentTime,out=audioOutput(volume,pan),noise=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter();noise.buffer=noiseBuffer;filter.type='lowpass';filter.frequency.value=420;noise.connect(filter);filter.connect(out);out.gain.setValueAtTime(volume,now);out.gain.exponentialRampToValueAtTime(.001,now+.11);noise.start(now);noise.stop(now+.13)}
function toggleAim(){if(player.dead||reloading)return;aiming=!aiming;if(aiming)zoomPower=Math.max(1.5,Math.min(2,zoomPower));targetFOV=aiming?(Math.PI/3)/zoomPower:Math.PI/3;document.body.classList.toggle('aiming',aiming);$('#zoomLevel').classList.toggle('hidden',!aiming);updateZoomLabel()}
addEventListener('keydown',e=>{if(e.code==='Tab'&&playing){e.preventDefault();renderScoreboard();$('#scoreboard').classList.remove('hidden')}});addEventListener('keyup',e=>{if(e.code==='Tab')$('#scoreboard').classList.add('hidden')});
function renderScoreboard(){const roster=[player,...others.values(),...bots];$('#boardBlue').textContent=blue;$('#boardRed').textContent=red;for(const side of ['blue','red']){const box=$('#'+side+'Board');box.innerHTML='';for(const p of roster.filter(x=>x.team===side).sort((a,b)=>(b.kills||0)-(a.kills||0))){const row=document.createElement('div');row.className='board-row'+(p.id===id?' me':'');row.innerHTML=`<span>${p.name||'OPERATOR'}<small>${WEAPONS[p.weapon]?.name||'K2 RIFLE'}</small></span><b>${p.kills||0}</b><b>${p.assists||0}</b><b>${p.deaths||0}</b>`;box.appendChild(row)}}}
function adjustZoom(e){if(!playing)return;e.preventDefault();if(!aiming){setFireMode(e.deltaY<0?'auto':'semi');return}zoomPower=Math.max(1.5,Math.min(2,Math.round((zoomPower+(e.deltaY<0?.1:-.1))*10)/10));targetFOV=(Math.PI/3)/zoomPower;updateZoomLabel()}
function setFireMode(mode){fireMode=mode;$('#fireMode').textContent=mode.toUpperCase();$('#fireMode').classList.toggle('semi',mode==='semi')}
function updateZoomLabel(){$('#zoomLevel').textContent=zoomPower.toFixed(1)+'X'}
function resetAim(){aiming=false;zoomPower=1.5;targetFOV=Math.PI/3;document.body.classList.remove('aiming');$('#zoomLevel').classList.add('hidden')}
function wall(x,y){if(MAP[Math.floor(y)]?.[Math.floor(x)]!=='0')return true;return ACTIVE_STRUCTURES.some(o=>Math.hypot(x-o.x,y-o.y)<o.r+.12)}
function loop(t){if(!playing)return;if(matchPaused){last=t;render();requestAnimationFrame(loop);return}const dt=Math.min((t-last)/1000,.04)||0;last=t;update(dt);render();requestAnimationFrame(loop)}
function update(dt){FOV+=(targetFOV-FOV)*Math.min(1,dt*10);updateSurrenderPanel();if(reloading){const now=performance.now(),p=Math.max(0,Math.min(1,(now-reloadStart)/(reloadEnd-reloadStart))),stage=p<.12?'TILT':p<.25?'MAG OUT':p<.4?'BACKPACK':p<.7?'LOADING':p<.9?'MAG IN':'READY';$('#ammo').textContent=Math.max(0,(reloadEnd-now)/1000).toFixed(1);$('#reserveAmmo').textContent='/ '+stage}if(firing&&fireMode==='auto')shoot();if(!player.dead&&document.pointerLockElement===canvas){let dx=0,dy=0,s=(aiming?2.35:3.1)*dt*(reloading?.5:1);if(keys.KeyW){dx+=Math.cos(player.a)*s;dy+=Math.sin(player.a)*s}if(keys.KeyS){dx-=Math.cos(player.a)*s;dy-=Math.sin(player.a)*s}if(keys.KeyA){dx+=Math.cos(player.a-1.57)*s;dy+=Math.sin(player.a-1.57)*s}if(keys.KeyD){dx+=Math.cos(player.a+1.57)*s;dy+=Math.sin(player.a+1.57)*s}if(!wall(player.x+dx,player.y))player.x+=dx;if(!wall(player.x,player.y+dy))player.y+=dy;send('state')}updateCasings(dt);
 for(const b of bots)updateBot(b,dt);for(const [k,v] of others)if(Date.now()-v.seen>3000)others.delete(k);if(solo&&currentMap==='training'){$('#timer').textContent='ESC EXIT';return}const left=Math.max(0,endAt-Date.now());$('#timer').textContent=`${String(left/60000|0).padStart(2,'0')}:${String((left/1000|0)%60).padStart(2,'0')}`;if(!left||blue>=100||red>=100){const winner=blue===red?'DRAW':blue>red?'BLUE':'RED';finishMatch(winner,true)}}
function finishMatch(winner,broadcast){if(matchEnding)return;matchEnding=true;playing=false;surrenderOpen=false;matchPaused=false;if(broadcast&&!solo)send('matchend',{winner,blue,red});if(document.pointerLockElement)document.exitPointerLock();$('#pause').classList.add('hidden');$('#surrenderModal').classList.add('hidden');$('#chatPanel').classList.add('hidden');$('#finalBlue').textContent=blue;$('#finalRed').textContent=red;const title=winner==='DRAW'?'DRAW':winner+' TEAM WINS';$('#winnerText').textContent=title;$('#winnerText').className=winner.toLowerCase();$('#matchEnd').classList.remove('hidden');let seconds=3;$('#returnTimer').textContent=seconds;const timer=setInterval(()=>{seconds--;$('#returnTimer').textContent=Math.max(0,seconds);if(seconds<=0){clearInterval(timer);returnAfterMatch(winner)}},1000)}
function returnAfterMatch(winner){$('#matchEnd').classList.add('hidden');$('#hud').classList.add('hidden');if(solo){$('#menu').classList.remove('hidden');bots.length=0;channel?.close();channel=null;currentRoom='';matchEnding=false;return}others.clear();isReady=false;for(const p of lobbyPlayers.values())p.ready=false;const me=lobbyPlayers.get(id);if(me)me.ready=false;$('#readyBtn').textContent='READY';$('#readyBtn').classList.remove('active');$('#matchLobby').classList.remove('hidden');$('#lobbyStatus').textContent=winner==='DRAW'?'Match ended in a draw. Ready for rematch.':winner+' TEAM WON - Ready for rematch.';updateHUD();matchEnding=false;updateLobby()}
function moveBot(b,tx,ty,dt,speed){const desired=Math.atan2(ty-b.y,tx-b.x),diff=Math.atan2(Math.sin(desired-b.a),Math.cos(desired-b.a));b.a+=diff*Math.min(1,dt*3.2);let nx=b.x+Math.cos(b.a)*dt*speed,ny=b.y+Math.sin(b.a)*dt*speed,moved=false;if(!wall(nx,b.y)){b.x=nx;moved=true}if(!wall(b.x,ny)){b.y=ny;moved=true}if(!moved){b.stuck=(b.stuck||0)+dt;if(b.stuck>.12){b.a+=Math.PI/2+(Math.random()-.5)*.7;nx=b.x+Math.cos(b.a)*dt*speed*1.6;ny=b.y+Math.sin(b.a)*dt*speed*1.6;if(!wall(nx,b.y)){b.x=nx;moved=true}if(!wall(b.x,ny)){b.y=ny;moved=true}}}else b.stuck=0;return{moved,diff}}
function botTarget(b){const candidates=[...bots,...others.values()];if(player.team!==b.team&&!player.dead)candidates.push(player);return candidates.filter(t=>t!==b&&!t.dead&&t.team!==b.team).sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y))[0]||null}
function clearSight(a,b){const d=Math.hypot(b.x-a.x,b.y-a.y);for(let z=.25;z<d-.2;z+=.2)if(wall(a.x+(b.x-a.x)*z/d,a.y+(b.y-a.y)*z/d))return false;return true}
function botHit(attacker,target,amount){const dist=Math.hypot(attacker.x-player.x,attacker.y-player.y),ang=Math.atan2(attacker.y-player.y,attacker.x-player.x)-player.a;playGunSound(attacker.weapon,Math.max(.05,.7-dist*.07),Math.sin(ang));if(target===player){damage(amount,attacker.name);return}if(!target.bot)return;target.hp-=amount;if(target.hp<=0)botKill(attacker,target)}
function awardTeamPoint(victimTeam){if(victimTeam==='blue')red++;else blue++;updateHUD();if(!solo)send('score',{blue,red})}
function botKill(attacker,target){if(target.dead)return;target.dead=true;target.hp=0;attacker.kills=(attacker.kills||0)+1;target.deaths=(target.deaths||0)+1;awardTeamPoint(target.team);feed(attacker.name,target.name);setTimeout(()=>respawnBot(target),2500)}
function updateBot(b,dt){if(b.dead)return;b.cool-=dt;let moved=false;const target=botTarget(b);if(target){const dist=Math.hypot(target.x-b.x,target.y-b.y),desired=Math.atan2(target.y-b.y,target.x-b.x),aimDiff=Math.atan2(Math.sin(desired-b.a),Math.cos(desired-b.a));if(dist>3.2){const motion=moveBot(b,target.x,target.y,dt,.86);moved=motion.moved}else b.a+=aimDiff*Math.min(1,dt*4);if(dist<7&&Math.abs(aimDiff)<.34&&clearSight(b,target)&&b.cool<=0){b.muzzle=performance.now()+90;botHit(b,target,WEAPONS[b.weapon]?.damage*.28||9);b.cool=(WEAPONS[b.weapon]?.delay||650)/230+Math.random()*.35}}else{const index=parseInt(b.id.replace('bot',''))||0,orbit=performance.now()/2600+index*2.4,tx=player.x+Math.cos(orbit)*2.1,ty=player.y+Math.sin(orbit)*2.1;if(Math.hypot(tx-b.x,ty-b.y)>.35){const motion=moveBot(b,tx,ty,dt,.82);moved=motion.moved}else b.a+=dt*.45}b.moving=moved;if(moved)b.walk=(b.walk||0)+dt*8}
function selectWeapon(id){if(!WEAPONS[id]||reloading)return;player.weapon=id;const gun=WEAPONS[id];player.ammo=gun.mag;player.reserve=gun.reserve;document.querySelectorAll('.weapon').forEach(b=>b.classList.toggle('active',b.dataset.weapon===id));updateHUD();send('state')}
function reload(){const gun=WEAPONS[player.weapon];if(reloading||matchPaused||player.ammo===gun.mag||player.reserve<=0)return;reloading=true;resetAim();reloadStart=performance.now();reloadEnd=reloadStart+gun.reload;const token=++reloadToken;$('#ammo').textContent=(gun.reload/1000).toFixed(1);$('#reserveAmmo').textContent='/ RELOADING';const complete=()=>{if(token!==reloadToken||!reloading)return;const wait=reloadEnd-performance.now();if(matchPaused||wait>0){setTimeout(complete,Math.max(100,Math.min(500,wait>0?wait:100)));return}const take=Math.min(gun.mag-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;reloading=false;reloadStart=reloadEnd=0;updateHUD()};setTimeout(complete,gun.reload)}
function shoot(){const gun=WEAPONS[player.weapon],now=performance.now();if(!playing||matchPaused||chatOpen||player.dead||reloading||now-lastShot<gun.delay)return;if(player.ammo<=0)return reload();lastShot=now;muzzleUntil=now+75;weaponKick=1;ejectCasing();player.ammo--;player.a+=(Math.random()-.5)*(player.weapon==='ak47'?.025:.012);updateHUD();let best=null,bd=player.weapon==='m16'?.1:.12;const range=solo&&currentMap==='training';for(const o of [...others.values(),...bots,...targets]){if(o.dead||(!range&&o.team===player.team))continue;const ang=Math.atan2(o.y-player.y,o.x-player.x),diff=Math.abs(Math.atan2(Math.sin(ang-player.a),Math.cos(ang-player.a))),dist=Math.hypot(o.x-player.x,o.y-player.y);if(diff<bd&&dist<18&&visible(o)){best=o;bd=diff}}if(best){$('#hitmarker').classList.remove('show');void $('#hitmarker').offsetWidth;$('#hitmarker').classList.add('show');if(best.type==='target')hitTarget(best);else if(best.bot){best.hp-=gun.damage;if(best.hp<=0)kill(best)}else send('shot',{target:best.id,damage:gun.damage})}else if(range){red++;updateHUD()}}
function hitTarget(target){if(target.dead)return;target.dead=true;blue++;player.kills++;updateHUD();feed(player.name,target.name);setTimeout(()=>{if(playing&&currentMap==='training')target.dead=false},700)}
function ejectCasing(){playGunSound(player.weapon,.72,0);casings.push({x:innerWidth/2+115,y:innerHeight-145,vx:120+Math.random()*110,vy:-170-Math.random()*90,rot:Math.random()*6.28,vr:8+Math.random()*12,life:1.35,bounce:false});if(casings.length>30)casings.shift()}
function updateCasings(dt){const now=performance.now(),walking=!player.dead&&document.pointerLockElement===canvas&&(keys.KeyW||keys.KeyA||keys.KeyS||keys.KeyD);if(walking&&now>nextFootstep){playFootstep(aiming?.12:.2,(Math.random()-.5)*.15);nextFootstep=now+(aiming?520:390)}for(const b of bots){if(b.dead||!b.moving)continue;const dist=Math.hypot(b.x-player.x,b.y-player.y);if(dist<9&&now>(b.nextStep||0)){const ang=Math.atan2(b.y-player.y,b.x-player.x)-player.a;playFootstep(Math.max(.025,.16-dist*.015),Math.sin(ang));b.nextStep=now+440+Math.random()*80}}for(const c of casings){c.vy+=620*dt;c.x+=c.vx*dt;c.y+=c.vy*dt;c.rot+=c.vr*dt;c.life-=dt;if(c.y>innerHeight-16&&!c.bounce){c.y=innerHeight-16;c.vy=-Math.abs(c.vy)*.28;c.vx*=.55;c.vr*=.7;c.bounce=true}}for(let i=casings.length-1;i>=0;i--)if(casings[i].life<=0)casings.splice(i,1)}
function visible(o){const d=Math.hypot(o.x-player.x,o.y-player.y);for(let z=.2;z<d;z+=.2)if(wall(player.x+(o.x-player.x)*z/d,player.y+(o.y-player.y)*z/d))return false;return true}
function damage(n,from){if(player.dead)return;damageSources.set(from,{time:Date.now(),damage:(damageSources.get(from)?.damage||0)+n});player.hp-=n;$('#damageFlash').style.opacity=1;setTimeout(()=>$('#damageFlash').style.opacity=0,100);updateHUD();if(player.hp<=0){player.dead=true;firing=false;resetAim();player.deaths++;const assists=[...damageSources.entries()].filter(([name,v])=>name!==from&&Date.now()-v.time<8000).map(([name])=>name),botKiller=bots.find(b=>b.name===from);if(botKiller)botKiller.kills=(botKiller.kills||0)+1;awardTeamPoint(player.team);feed(from,player.name);send('death',{killer:from,assists});damageSources.clear();let c=3;$('#respawn').classList.remove('hidden');$('#respawnTime').textContent=c;const q=setInterval(()=>{if(--c<=0){clearInterval(q);$('#respawn').classList.add('hidden');spawn()}else $('#respawnTime').textContent=c},1000)}}
function kill(o){if(o.dead)return;o.dead=true;o.hp=0;player.kills++;o.deaths=(o.deaths||0)+1;awardTeamPoint(o.team);feed(player.name,o.name);setTimeout(()=>respawnBot(o),2500)}
function respawnBot(o){if(!playing)return;const pts=teamSpawns(o.team),p=pts[Math.random()*pts.length|0];o.x=p[0];o.y=p[1];o.a=o.team==='blue'?-Math.PI/2:Math.PI/2;o.hp=100;o.cool=1.2;o.stuck=0;o.dead=false}
function feed(a,b){const d=document.createElement('div');d.innerHTML=`<b>${a}</b> ▸ ${b}`;$('#killfeed').prepend(d);setTimeout(()=>d.remove(),3500)}
function halfDown2(value){const safe=Math.max(0,Math.min(100,value)),scaled=safe*100,base=Math.floor(scaled),fraction=scaled-base;return (fraction>.5?base+1:base)/100}
function updateHUD(){const gun=WEAPONS[player.weapon],health=Math.max(0,player.hp);$('#health').textContent=halfDown2(health).toFixed(2)+'%';$('#healthBar').style.width=health+'%';$('#healthBar').style.background=player.hp<35?'var(--red)':'var(--cyan)';$('#ammo').textContent=player.ammo;$('#weaponName').textContent=gun.name;$('#weaponName').style.color=gun.color;$('#reserveAmmo').textContent='/ '+player.reserve;$('#blueScore').textContent=blue;$('#redScore').textContent=red}
